tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(180deg,#ff0000_-20%,#00ff00_50%,#0000ff_130%)]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(180deg, #ff0000 -20%, #00ff00 50%, #0000ff 130%);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(180deg, #ff0000 -20%, #00ff00 50%, #0000ff 130%);
}

css-variables:
:root {
  --gradient-angle: 180deg;
  --gradient-color-1: #ff0000;
  --gradient-position-1: -20%;
  --gradient-color-2: #00ff00;
  --gradient-position-2: 50%;
  --gradient-color-3: #0000ff;
  --gradient-position-3: 130%;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1) var(--gradient-position-1), var(--gradient-color-2) var(--gradient-position-2), var(--gradient-color-3) var(--gradient-position-3));
}

/* Usage: background: var(--gradient); */

